def poly(u, d=2):
    from itertools import combinations_with_replacement
    return np.column_stack([np.ones(len(u))] + [u[:, i].prod(1) for j in range(1, d + 1) for i in combinations_with_replacement(range(u.shape[1]), j)])

def panel_fit(p, k, f, typ):
    from scipy.optimize import minimize_scalar
    u = p['u']
    v = p[k]
    a = aff(u)
    base = [a, np.ones((len(u), 1))][typ]

    def compute(w):
        P = np.c_[base, f(w * u)]
        return (P, fit(P, v))

    def loss(w):
        (P, b) = compute(w)
        return np.mean((P @ b - v) ** 2)
    g = np.linspace(0.05, 5, 100)
    z = min(g, key=loss)
    o = minimize_scalar(loss, bounds=(max(0.01, z - 0.07), z + 0.07), method='bounded')
    (P, b) = compute(o.x)
    return (o.fun ** 0.5, o.x, b)

def stats(A, v, ret=False):
    b = np.linalg.lstsq(A, v, rcond=1e-09)[0]
    e = A @ b - v
    h = (np.linalg.svd(A, full_matrices=False)[0] ** 2).sum(1)
    return (e, b) if ret else np.mean(abs(e / np.maximum(1e-08, 1 - h[:, None])))
